import { MakeLogicType, actions, kea, listeners, path } from 'kea'
import posthog from 'posthog-js'

export type BillingHelpContactMethod = 'email' | 'support'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface billingHelpLogicActions {
    reportBillingHelpContactClicked: (method: BillingHelpContactMethod) => {
        method: BillingHelpContactMethod
    }
    reportBillingHelpCtaClicked: () => {
        value: true
    }
    reportBillingHelpLinkClicked: (link: string) => {
        link: string
    }
    reportBillingHelpViewed: (hasAccountContact: boolean) => {
        hasAccountContact: boolean
    }
}

export type billingHelpLogicType = MakeLogicType<{}, billingHelpLogicActions>

export const billingHelpLogic = kea<billingHelpLogicType>([
    path(['scenes', 'billing', 'billingHelpLogic']),
    actions({
        reportBillingHelpCtaClicked: true,
        reportBillingHelpViewed: (hasAccountContact: boolean) => ({ hasAccountContact }),
        reportBillingHelpLinkClicked: (link: string) => ({ link }),
        reportBillingHelpContactClicked: (method: BillingHelpContactMethod) => ({ method }),
    }),
    listeners({
        reportBillingHelpCtaClicked: () => {
            posthog.capture('billing help cta clicked')
        },
        reportBillingHelpViewed: ({ hasAccountContact }) => {
            posthog.capture('billing help viewed', { has_account_contact: hasAccountContact })
        },
        reportBillingHelpLinkClicked: ({ link }) => {
            posthog.capture('billing help link clicked', { link })
        },
        reportBillingHelpContactClicked: ({ method }) => {
            posthog.capture('billing help contact clicked', { method })
        },
    }),
])
